package mx.gob.sedesol.basegestor.gestionescolar.v2;
import static org.testng.Assert.*; import org.testng.annotations.Test; import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.*; import mx.gob.sedesol.basegestor.service.impl.gestionescolar.v2.EvaluacionCurricularV2ServiceImpl;
public class EvaluacionCurricularV2Fase6ATest { private final EvaluacionCurricularV2ServiceImpl s = new EvaluacionCurricularV2ServiceImpl();
 @Test public void admitidoSinInscripcionS2(){assertEquals(x(c()).getEstadoIncorporacionDiferida(),EstadoIncorporacionDiferidaV2.INCORPORACION_SEMESTRE_2_PROCEDE_EN_SOMBRA);}
 @Test public void yaInscritoNoAplica(){ContextoEvaluacionCurricularV2DTO z=c();z.setInscripcionInicialRealizada(true);assertFalse(x(z).getAplicaRn62());}
 @Test public void seriacionBloquea(){ContextoEvaluacionCurricularV2DTO z=c();z.getUnidades().get(0).setSeriacionDirectaConocida(true);assertEquals(x(z).getEstadoIncorporacionDiferida(),EstadoIncorporacionDiferidaV2.INCORPORACION_SEMESTRE_2_NO_PROCEDE_POR_SERIACION);}
 @Test public void inactividadSeIdentificaSinDenegacionAutomatica(){ContextoEvaluacionCurricularV2DTO z=c();z.setLimiteInactividadAlcanzado(true);assertEquals(x(z).getEstadoIncorporacionDiferida(),EstadoIncorporacionDiferidaV2.INCORPORACION_SEMESTRE_2_PROCEDE_EN_SOMBRA);}
 @Test public void sinReferenciaRequiereRevision(){ContextoEvaluacionCurricularV2DTO z=c();z.setReferenciaConvocatoriaOResolucionRn62(null);assertEquals(x(z).getEstadoIncorporacionDiferida(),EstadoIncorporacionDiferidaV2.REQUIERE_REVISION);}
 @Test public void noEsEfecto(){assertFalse(s.evaluarSombra(c()).getEfectosProductivosAplicados());}
 private EvaluacionCargaAcademicaV2DTO x(ContextoEvaluacionCurricularV2DTO z){return s.evaluarSombra(z).getEvaluacionCargaAcademica();}
 private ContextoEvaluacionCurricularV2DTO c(){ContextoEvaluacionCurricularV2DTO z=new ContextoEvaluacionCurricularV2DTO();z.setAdmitido(true);z.setInscripcionInicialRealizada(false);z.setActividadAcademicaComprobada(true);z.setReferenciaConvocatoriaOResolucionRn62("CONVOCATORIA-PRUEBA");UnidadEvaluacionCurricularV2DTO u=new UnidadEvaluacionCurricularV2DTO();u.setIdPrograma(2L);u.setTipoUd("Obligatoria");u.setSemestre(2);u.setEstado(EstadoUnidadCurricularV2.NO_CURSADA);u.setOfertada(true);z.getUnidades().add(u);return z;}}
